export default function (clay) {
  clay.db.watch({ from: "expenses", limit: 500 }, (rows) => {
    clay.ui.render(rows.length === 0
      ? h(EmptyState, { label: "No rows yet" })
      : h(Table, { sortable: true, rows, columns: [{ field: "item", label: "item" }, { field: "amount", label: "amount", format: "number" }] }));
  });
}

